#!/usr/bin/env python3
# SPDX-FileCopyrightText: 2026 Core Devices LLC
# SPDX-License-Identifier: Apache-2.0
"""Generate zephyr_bt_config.h from Zephyr's own Bluetooth Kconfig.

Usage: gen_config.py ZEPHYR_TREE

ZEPHYR_TREE is the Zephyr submodule (../zephyr); only its subsys/bluetooth
Kconfig files and the logging Kconfig templates are read. Defaults and dependencies are Zephyr's, so the header
matches what a Zephyr build with pebble.conf would use.
"""

import os
import sys

import kconfiglib

HERE = os.path.dirname(os.path.abspath(__file__))

# BT_CLASSIC selects the LE roles and SMP. NimBLE owns LE, so drop those
# selects; the port keeps LE connections (BT_CONN) through PEBBLE_ZBT.
# PBAP selects OBEX authentication (MD5 over PSA crypto); phones' phone book servers do not ask
# for it, so it is left out.
CUT_SELECTS = {
    "BT_CLASSIC": ["BT_PERIPHERAL", "BT_CENTRAL", "BT_SMP"],
    "BT_PBAP": ["BT_OBEX_AUTH"],
}

# Zephyr options outside Bluetooth that the host and its headers read.
EXTRA = """
/* Zephyr options outside Bluetooth, for the PebbleOS port */
#define CONFIG_ARM 1
#define CONFIG_ARMV8_M_MAINLINE 1
#define CONFIG_ATOMIC_OPERATIONS_BUILTIN 1
#define CONFIG_LITTLE_ENDIAN 1
#define CONFIG_SYS_CLOCK_TICKS_PER_SEC 1000
#define CONFIG_SYS_CLOCK_HW_CYCLES_PER_SEC 1000
#define CONFIG_SYS_CLOCK_MAX_TIMEOUT_DAYS 365
#define CONFIG_TIMEOUT_64BIT 1
#define CONFIG_NUM_COOP_PRIORITIES 16
#define CONFIG_NUM_PREEMPT_PRIORITIES 15
#define CONFIG_MP_MAX_NUM_CPUS 1
#define CONFIG_NET_BUF 1
#define CONFIG_NET_BUF_ALIGNMENT 0

/* No dedicated no-init section: plain .bss */
#define __noinit
"""


def main():
    zephyr = os.path.abspath(sys.argv[1])
    os.environ["srctree"] = zephyr
    os.chdir(zephyr)

    k = kconfiglib.Kconfig(
        os.path.join(HERE, "Kconfig.zephyr_bt"), warn_to_stderr=False
    )
    for selector, targets in CUT_SELECTS.items():
        sym = k.syms[selector]
        sym.selects = [(t, c) for (t, c) in sym.selects if t.name not in targets]
        for t in targets:
            k.syms[t].rev_dep = k.n

    k.load_config(os.path.join(HERE, "pebble.conf"))
    bad = [w for w in k.warnings if "was assigned the value" in w]
    if bad:
        sys.exit("\n".join(bad))

    tmp = os.path.join(HERE, "zephyr_bt_config.h.tmp")
    k.write_autoconf(tmp)
    with open(tmp) as f:
        defines = [line for line in f if line.startswith("#define")]
    os.remove(tmp)

    with open(os.path.join(HERE, "zephyr_bt_config.h"), "w") as f:
        f.write("/* SPDX-FileCopyrightText: 2026 Core Devices LLC */\n")
        f.write("/* SPDX-License-Identifier: Apache-2.0 */\n\n")
        f.write("/* Generated by gen_config.py from pebble.conf; do not edit. */\n\n")
        f.write("/* PebbleOS uses this name for its own log level. */\n")
        f.write("#undef CONFIG_BT_LOG_LEVEL\n\n")
        f.writelines(defines)
        f.write(EXTRA)


if __name__ == "__main__":
    main()
